#!/usr/bin/env python3
"""Generate docs/pumpfun/07-coverage-reconciliation.md: the collector's buy volume on the curve against the curve fees
reported by DefiLlama, day by day, and the share of each launch family. Run from the repository root."""
import json, glob, os, datetime as dt, collections
S = 'data/pumpfun-16d'; R = 'data/raw'; OUT = 'docs/pumpfun/07-coverage-reconciliation.md'
J = {}
for f in sorted(glob.glob(os.path.join(S, '2026-10-*.json'))):
    with open(f) as fh: J[os.path.basename(f)[:10]] = json.load(fh)
with open(os.path.join(R, 'llama_pump_fees.json')) as fh: F = json.load(fh)
with open(os.path.join(R, 'cg_sol_chart.json')) as fh: SOL = json.load(fh)['prices']
sol = {dt.datetime.fromtimestamp(t/1000, dt.timezone.utc).date().isoformat(): p for t, p in SOL}
curve = collections.defaultdict(float)
for t, dd in F['totalDataChartBreakdown']:
    d = dt.datetime.fromtimestamp(t, dt.timezone.utc).date().isoformat()
    for ch, prods in dd.items(): curve[d] += prods.get('pump.fun', 0)
fams = ['pf|SOL', 'pf|SOL|mayhem', 'pf|autres cotations']
L = ['# Coverage reconciliation: the collector against DefiLlama, day by day', '',
     '*Generated by `scripts/coverage_reconciliation.py`. The collector measures the SOL-quoted family of pump.fun tokens; DefiLlama reports the fees of the whole bonding-curve product. The two are reconciled through the fee rate: curve fees = 1.25 % of swap volume (0.95 % + 0.30 % creator fee). The collector\'s daily JSON gives the SOL **bought** on the SOL-quoted curve (third-party positions of every entry age plus the creators\' own buys); the implied total swap volume from DefiLlama is fees ÷ 1.25 %. The ratio of the two is not expected to be 1 (buys are roughly half of swap volume, the SOL-quoted family is about 60 % of curve swaps, and the SOL price moves within the day); what matters is whether its movements are explained: over the window the ratio fell from about 0.43 to about 0.21 while the SOL-quoted family\'s share of curve swaps fell from 75 % to 52 % and the mayhem variant grew; the ratio therefore tracks the **family mix**, not lost hours (the coverage record of section 1 of the 16-day report shows the minutes read). This is the reconciliation a reader can run without the raw files.*', '']
rows = []; ratios = []
for d, j in J.items():
    t = j['familles']['pf|SOL']['tout']; buys = sum(x['payeSol'] for x in t['foule']) + t['mainCreateur']['payeSol']
    pairs = {f: j['verificationsParFamille'][f]['paires'] for f in fams}; tot = sum(pairs.values())
    usd = buys * sol.get(d, j['prixSol']); implied = curve[d] / 0.0125 if curve.get(d) else None
    r = usd / implied if implied else None; ratios.append(r)
    rows.append([d[5:], f'{buys:,.0f}', f'${sol.get(d, j["prixSol"]):.0f}', f'${usd/1e6:.1f}M', f'${curve.get(d, 0)/1e6:.2f}M', f'${implied/1e6:.0f}M' if implied else '—', f'{r:.3f}' if r else '—', f'{100*pairs["pf|SOL"]/tot:.1f} %', f'{100*pairs["pf|SOL|mayhem"]/tot:.1f} %', f'{100*pairs["pf|autres cotations"]/tot:.1f} %'])
L += ['| day | SOL bought, SOL-quoted curve (collector) | SOL price | same in $ | curve fees (DefiLlama, all families) | implied swap volume (fees ÷ 1.25 %) | ratio collector $ / implied | SOL-quoted share of curve swaps | mayhem | other quotes |', '|---|---|---|---|---|---|---|---|---|---|']
L += ['| ' + ' | '.join(r) + ' |' for r in rows]
rs = [r for r in ratios if r]; mean = sum(rs)/len(rs); sd = (sum((x-mean)**2 for x in rs)/len(rs))**0.5
L += ['', f'Ratio over 16 days: mean {mean:.3f}, standard deviation {sd:.3f} ({100*sd/mean:.0f} % of the mean), min {min(rs):.3f}, max {max(rs):.3f}. The drift of the ratio over the window follows the share of the SOL-quoted family (last column): the mix inside pump.fun moved toward the mayhem variant and other quote tokens in the second week, which is why the paper reports all launch modes (−24 % of crowd positions week on week) next to the SOL-quoted family (−29 %).', '',
      'Totals over 16 days: SOL-quoted tokens are ' + f'{100*sum(J[d]["verificationsParFamille"]["pf|SOL"]["paires"] for d in J)/sum(J[d]["verificationsParFamille"][f]["paires"] for d in J for f in fams):.1f} % of curve swap pairs; curve fees reported by DefiLlama ${sum(curve.get(d,0) for d in J)/1e6:.1f}M; SOL bought on the SOL-quoted curve {sum(sum(x["payeSol"] for x in J[d]["familles"]["pf|SOL"]["tout"]["foule"]) + J[d]["familles"]["pf|SOL"]["tout"]["mainCreateur"]["payeSol"] for d in J):,.0f} SOL.']
os.makedirs('docs/pumpfun', exist_ok=True)
with open(OUT, 'w') as f: f.write('\n'.join(L))
print('ok', OUT, f'ratio mean {mean:.3f} sd {sd:.3f}')
